/* Productos, Inventario, Compras, Proveedores, Clientes, Gastos, Reportes, Ajustes y arranque. */
'use strict';
const provsDe=p=>[...new Set(S.catalogo.filter(c=>c.productoId===p.id).map(c=>c.proveedorId))].map(id=>IDX.prov[id]).filter(Boolean);
const dot=c=>`<span class="sw" style="background:${esc(c||'#999')}"></span>`;
const selProductos=(extraVacio)=>(extraVacio?[{v:'',t:'— Elegí un producto —'}]:[]).concat(S.productos.filter(p=>p.activo).sort((a,b)=>a.nombre.localeCompare(b.nombre)).map(p=>({v:p.id,t:p.codigo+' · '+p.nombre})));
const selProveedores=(vacio)=>(vacio?[{v:'',t:vacio}]:[]).concat(S.proveedores.slice().sort((a,b)=>a.nombre.localeCompare(b.nombre)).map(v=>({v:v.id,t:v.nombre})));
const mgPill=p=>{ const m=margen(p); return p.precio>0?pill(m<20?'bad':m<30?'warn':'good',fmt(m,0)+'%'):pill('mute','—'); };

/* ================= PRODUCTOS ================= */
VIEWS.productos=function(){ const f=UI.f.prod;
  return `${encab('Productos','Catálogo, precios y márgenes',`<button class="btn pri" data-act="prod-nuevo">Nuevo producto</button><button class="btn" data-act="prod-precios">Actualizar precios</button><button class="btn" data-act="prod-unidad">Unidad por categoría</button><button class="btn" data-act="prod-import">Importar</button><button class="btn" data-act="prod-export">Exportar</button>`)}
  <div class="filters"><label class="field">Buscar<input data-bind="f.prod.q" value="${esc(f.q)}" placeholder="Nombre, código o código de barras"></label>
   <label class="field">Categoría<select data-bind="f.prod.cat"><option value="">Todas</option>${opts(cats(),f.cat)}</select></label>
   <label class="field">Proveedor<select data-bind="f.prod.prov">${opts(selProveedores('Todos'),f.prov)}</select></label>
   <label class="field">Ver<select data-bind="f.prod.ver">${opts([{v:'',t:'Todos'},{v:'sin',t:'Sin stock'},{v:'bajo',t:'Stock bajo o sin stock'},{v:'precio',t:'Precio desactualizado'},{v:'margen',t:'Margen bajo (menos de 20%)'}],f.ver)}</select></label>
   <label class="field">Estado<select data-bind="f.prod.est">${opts([{v:'activos',t:'Activos'},{v:'inactivos',t:'Inactivos'},{v:'todos',t:'Todos'}],f.est)}</select></label></div><div id="res"></div>`; };
FILL.productos=function(){ const r=$('#res'); if(!r) return; const f=UI.f.prod; const q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  const l=S.productos.filter(p=>{ if(f.est==='activos'&&!p.activo) return false; if(f.est==='inactivos'&&p.activo) return false; if(f.cat&&p.categoria!==f.cat) return false;
    if(f.prov&&!S.catalogo.some(c=>c.productoId===p.id&&String(c.proveedorId)===String(f.prov))) return false;
    if(q&&!(p.nombre.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||p.codigo.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||(p.barras||'').includes(q)||(p.categoria||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))) return false;
    const s=stockDe(p.id); if(f.ver==='sin'&&s>0) return false; if(f.ver==='bajo'&&s>p.minimo) return false; if(f.ver==='margen'&&!(p.precio>0&&margen(p)<20)) return false;
    if(f.ver==='precio'){ const d=diasPrecio(p); if(!(d!=null&&d>S.config.diasPrecio)) return false; } return true; }).sort((a,b)=>a.nombre.localeCompare(b.nombre));
  r.innerHTML=(l.length?`<div class="sm muted" style="margin-bottom:6px">${l.length} producto${l.length>1?'s':''}</div><div class="tw"><table><thead><tr><th>Producto</th><th class="n">Stock</th><th class="n">Mínimo</th><th class="n">Costo</th><th class="n">Precio</th><th class="c">Margen</th><th>Proveedor</th><th>Alerta</th></tr></thead><tbody>${l.map(p=>{ const s=stockDe(p.id); const d=diasPrecio(p); const pv=provsDe(p);
    return `<tr class="click ${p.activo?'':'off'}" data-act="prod-edit" data-id="${p.id}"><td><b>${esc(p.nombre)}</b><div class="sm muted">${esc(p.codigo)}${p.categoria?' · '+esc(p.categoria):''}</div></td><td class="n b ${s<=0?'dn':s<=p.minimo?'':''}">${qtyTxt(p,s)}</td><td class="n">${qtyTxt(p,p.minimo)}</td><td class="n">${money2(p.costo)}</td><td class="n b">${money2(p.precio)}</td><td class="c">${mgPill(p)}</td><td>${pv.length?pv.map(v=>dot(v.color)+esc(v.nombre)).join('<br>'):'<span class="muted">—</span>'}</td>
    <td>${!p.activo?pill('mute','Inactivo'):s<=0?pill('bad','Sin stock'):s<=p.minimo?pill('warn','Stock bajo'):''}${d!=null&&d>S.config.diasPrecio?' '+pill('info','Precio viejo'):''}</td></tr>`; }).join('')}</tbody></table></div>`:vacioHtml(S.productos.length?'No hay productos con esos filtros.':'Todavía no hay productos. Creá el primero o importá una lista.')); };
AFTER.productos=()=>FILL.productos();
function camposProducto(p){ const nuevo=!p;
  const c=[{n:'nombre',l:'Nombre',t:'text',req:true,full:true},{n:'codigo',l:'Código interno',t:'text',ro:!nuevo,ph:'Se genera solo'},{n:'barras',l:'Código de barras',t:'text',ph:'Opcional'},
    {n:'categoria',l:'Categoría',t:'text',list:cats().concat(RUBROS[S.config.rubro]?RUBROS[S.config.rubro].cats:[]).filter((x,i,a)=>a.indexOf(x)===i)}];
  if(S.config.peso) c.push({n:'unidad',l:'Se vende por',t:'select',o:[{v:'u',t:'Unidad'},{v:'kg',t:'Peso (kg)'}]});
  c.push({n:'costo',l:'Costo ($)',t:'num',min:0,live:'margen'},{n:'precio',l:'Precio de venta ($)',t:'num',min:0,live:'margen',hint:''},{n:'minimo',l:'Stock mínimo',t:'num',min:0});
  if(nuevo){ c.push({n:'stock',l:'Stock inicial',t:'num',min:0},{n:'proveedor',l:'Proveedor (opcional)',t:'select',o:selProveedores('(ninguno)')}); }
  c.push({n:'activo',l:'Producto activo',t:'check'},{n:'notas',l:'Notas',t:'area',full:true}); return c; }
LIVE.margen=()=>{ const c=num($('#f_costo').value),p=num($('#f_precio').value),h=$('#h_precio'); if(!h) return; h.textContent=(p>0&&c!=null)?'Margen: '+fmt((p-c)/p*100,1)+'%  ·  Ganancia por unidad: '+money2(p-c):''; };
ACT['prod-nuevo']=()=>prodForm(null);
ACT['prod-edit']=el=>prodForm(prod(+el.dataset.id));
function prodForm(p){ const nuevo=!p; const vals=p?Object.assign({},p):{unidad:'u',activo:true,costo:'',precio:'',minimo:''};
  const foot=p?`<button class="btn sm" data-act="prod-mover" data-id="${p.id}" type="button">Mover stock</button><button class="btn sm" data-act="prod-hist" data-id="${p.id}" type="button">Historial de precios</button><button class="btn sm bad" data-act="prod-del" data-id="${p.id}" type="button">Eliminar</button><span style="flex:1"></span>`:'';
  formModal(nuevo?'Nuevo producto':'Editar producto',camposProducto(p),vals,d=>{
    if(S.productos.some(x=>x.nombre.toLowerCase()===d.nombre.toLowerCase()&&(!p||x.id!==p.id))) throw new Error('Ya existe un producto llamado «'+d.nombre+'».');
    if(d.barras&&S.productos.some(x=>x.barras&&x.barras===d.barras&&(!p||x.id!==p.id))) throw new Error('Ese código de barras ya está en otro producto.');
    if(!nuevo&&Math.abs(p.costo-d.costo)>=0.005) S.historial.push({id:sig('H'),fecha:hoy(),productoId:p.id,proveedorId:0,precio:d.costo,origen:'Ficha del producto'});
    const q=guardarProducto(Object.assign({},d,{codigo:nuevo?'':p.codigo,unidad:d.unidad||'u'}),p?p.id:null);
    if(nuevo){ if(d.stock>0) mov(q.id,'Entrada',d.stock,'Stock inicial'); if(d.proveedor&&d.costo>0) registrarPrecio(q.id,+d.proveedor,d.costo,hoy(),'Ficha del producto'); }
    guardar(); cerrar(); refrescar(); toast(nuevo?'Producto creado':'Producto guardado'); },{wide:true,foot});
  LIVE.margen(); }
ACT['prod-del']=el=>{ const p=prod(+el.dataset.id);
  if(S.ventas.some(v=>v.items.some(i=>i.productoId===p.id))||S.compras.some(c=>c.items.some(i=>i.productoId===p.id))){ toast('«'+p.nombre+'» tiene ventas o compras. Para no perder el historial, marcalo como inactivo.',true); return; }
  confirmar('¿Eliminar «'+esc(p.nombre)+'» con sus movimientos y precios? No se puede deshacer.',()=>{ S.productos=S.productos.filter(x=>x.id!==p.id); S.movimientos=S.movimientos.filter(x=>x.productoId!==p.id); S.lotes=S.lotes.filter(x=>x.productoId!==p.id); S.catalogo=S.catalogo.filter(x=>x.productoId!==p.id); S.historial=S.historial.filter(x=>x.productoId!==p.id); indexar(); guardar(); refrescar(); toast('Producto eliminado'); },'Eliminar'); };
ACT['prod-mover']=el=>moverForm(prod(+el.dataset.id));
ACT['prod-hist']=el=>{ const p=prod(+el.dataset.id); const h=S.historial.filter(x=>x.productoId===p.id).sort((a,b)=>a.fecha<b.fecha?-1:a.fecha>b.fecha?1:a.id-b.id); const ant={};
  const filas=h.map(x=>{ const k=x.proveedorId; const v=ant[k]!=null&&ant[k]>0?(x.precio-ant[k])/ant[k]*100:null; ant[k]=x.precio; return {x,v}; }).reverse();
  abrir('Historial de precios · '+p.nombre,filas.length?`<div class="tw"><table><thead><tr><th>Fecha</th><th>Proveedor</th><th class="n">Precio</th><th class="n">Variación</th><th>Origen</th></tr></thead><tbody>${filas.map(({x,v})=>`<tr><td>${fechaTxt(x.fecha)}</td><td>${esc(x.proveedorId?provNom(x.proveedorId):'Ficha')}</td><td class="n">${money2(x.precio)}</td><td class="n ${v>0?'dn':v<0?'up':''}">${v==null?'—':(v>0?'+':'')+fmt(v,1)+'%'}</td><td>${esc(x.origen)}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Todavía no hay cambios de precio registrados.'),{wide:true,foot:'<button class="btn pri" data-act="cerrar">Cerrar</button>'}); };

/* actualización masiva de precios (inflación) */
function planPrecios(d){ const m=d.modo; const r=num(d.redondeo)||0; const v=d.valor||0;
  const rd=x=>r>0?Math.round(x/r)*r:r2(x);
  return S.productos.filter(p=>p.activo&&(!d.cat||p.categoria===d.cat)&&(!d.prov||S.catalogo.some(c=>c.productoId===p.id&&String(c.proveedorId)===String(d.prov)))).map(p=>{
    let c=p.costo,pr=p.precio;
    if(m==='pct'){ if(d.ajustar!=='precio') c=r2(p.costo*(1+v/100)); if(d.ajustar!=='costo') pr=rd(p.precio*(1+v/100)); }
    else { pr=v<100?rd(p.costo/(1-v/100)):p.precio; }
    return {p,c,pr}; }); }
function leerPrecios(){ const f=$('#frm'); return {cat:f.elements.cat.value,prov:f.elements.prov.value,modo:f.elements.modo.value,ajustar:f.elements.ajustar.value,valor:num(f.elements.valor.value)||0,redondeo:f.elements.redondeo.value}; }
LIVE.prbulk=()=>{ const d=leerPrecios(); const pl=planPrecios(d); const e=$('#prv'); if(!e) return;
  e.innerHTML=pl.length?`<p class="sm"><b>${pl.length}</b> producto${pl.length>1?'s':''} se van a modificar. Ejemplos:</p><div class="tw"><table><thead><tr><th>Producto</th><th class="n">Costo</th><th class="n">Precio</th><th class="c">Margen</th></tr></thead><tbody>${pl.slice(0,5).map(x=>`<tr><td>${esc(x.p.nombre)}</td><td class="n">${money2(x.p.costo)} → ${money2(x.c)}</td><td class="n">${money2(x.p.precio)} → <b>${money2(x.pr)}</b></td><td class="c">${x.pr>0?fmt((x.pr-x.c)/x.pr*100,0)+'%':'—'}</td></tr>`).join('')}</tbody></table></div>`:'<p class="sm muted">No hay productos con ese alcance.</p>'; };
ACT['prod-precios']=()=>{ const campos=[{n:'cat',l:'Categoría',t:'select',o:[{v:'',t:'Todas'}].concat(cats()),live:'prbulk'},{n:'prov',l:'Proveedor',t:'select',o:selProveedores('Todos'),live:'prbulk'},
  {n:'modo',l:'Cómo ajustar',t:'select',o:[{v:'pct',t:'Aumentar o bajar un porcentaje'},{v:'margen',t:'Fijar margen objetivo (sobre el costo actual)'}],live:'prbulk'},{n:'ajustar',l:'Qué ajustar (modo porcentaje)',t:'select',o:[{v:'ambos',t:'Costo y precio de venta'},{v:'precio',t:'Solo precio de venta'},{v:'costo',t:'Solo costo'}],live:'prbulk'},
  {n:'valor',l:'Porcentaje (%) o margen objetivo (%)',t:'num',live:'prbulk',ph:'Ej: 8'},{n:'redondeo',l:'Redondear precios de venta a',t:'select',o:[{v:'0',t:'Centavos (sin redondeo)'},{v:'10',t:'$10'},{v:'50',t:'$50'},{v:'100',t:'$100'}],live:'prbulk'}];
  formModal('Actualizar precios en bloque',campos,{modo:'pct',ajustar:'ambos',redondeo:'10'},d=>{ const dd=leerPrecios(); if(!dd.valor) throw new Error('Ingresá el porcentaje.'); if(dd.modo==='margen'&&(dd.valor<=0||dd.valor>=100)) throw new Error('El margen objetivo tiene que estar entre 0 y 100.');
    const pl=planPrecios(dd); if(!pl.length) throw new Error('No hay productos con ese alcance.'); pl.forEach(x=>{ x.p.costo=x.c; x.p.precio=x.pr; }); guardar(); cerrar(); refrescar(); toast(pl.length+' productos actualizados'); },{wide:true,okText:'Aplicar cambios',extra:'<div id="prv" style="margin-top:12px"></div>'}); LIVE.prbulk(); };
ACT['prod-unidad']=()=>{ if(!cats().length){ toast('Todavía no hay categorías cargadas.',true); return; }
  formModal('Unidad de venta por categoría',[{n:'cat',l:'Categoría',t:'select',o:cats(),full:true},{n:'unidad',l:'Se vende por',t:'select',o:[{v:'kg',t:'Peso (kg)'},{v:'u',t:'Unidad'}],full:true}],{unidad:'kg'},d=>{ let n=0; S.productos.forEach(p=>{ if(p.categoria===d.cat&&p.unidad!==d.unidad){ p.unidad=d.unidad; n++; } }); guardar(); cerrar(); refrescar(); toast(n+' producto'+(n===1?'':'s')+' actualizado'+(n===1?'':'s')); },{okText:'Aplicar'}); };
ACT['prod-export']=()=>{ const rows=S.productos.map(p=>[p.codigo,p.nombre,p.categoria,p.unidad,fmt(p.costo,2).replace(/\./g,''),fmt(p.precio,2).replace(/\./g,''),fmt(stockDe(p.id),3).replace(/\./g,''),fmt(p.minimo,3).replace(/\./g,''),p.barras,(provsDe(p)[0]||{}).nombre||'']);
  descargar('productos_'+hoy()+'.csv',aCSV(['codigo','nombre','categoria','unidad','costo','precio','stock','minimo','barras','proveedor'],rows)); };
ACT['prod-import']=()=>{ abrir('Importar productos',`<p style="margin-top:0">Subí un archivo CSV (podés guardarlo desde Excel con «Guardar como CSV»). Los productos con el mismo código se <b>actualizan</b> y los nuevos se crean. Columnas reconocidas: <span class="sm muted">codigo, nombre, categoria, unidad (u o kg), costo, precio, stock, minimo, barras, proveedor</span>. Solo «nombre» es obligatoria.</p>
  <input type="file" id="impf" accept=".csv,.txt"><div id="impr" class="sm" style="margin-top:10px"></div>`,{foot:`<button class="btn" id="modelo">Descargar modelo</button><button class="btn pri" data-act="cerrar">Cerrar</button>`});
  $('#modelo').onclick=()=>descargar('modelo_productos.csv',aCSV(['codigo','nombre','categoria','unidad','costo','precio','stock','minimo','barras','proveedor'],[['FIA010','Jamón cocido natural','Fiambres','kg','9800','14500','12','3','','Frigorífico Don Pepe']]));
  $('#impf').onchange=e=>{ const f=e.target.files[0]; if(!f) return; const rd=new FileReader(); rd.onload=()=>{ try{ const r=importarProductosCSV(String(rd.result)); refrescar(); $('#impr').innerHTML=`<b class="up">Listo.</b> Productos nuevos: ${r.nuevos}. Actualizados: ${r.act}.${r.errores.length?'<br><span class="dn">'+r.errores.slice(0,8).map(esc).join('<br>')+'</span>':''}`; }catch(err){ $('#impr').innerHTML='<span class="dn">'+esc(err.message)+'</span>'; } }; rd.readAsText(f,'utf-8'); }; };

/* ================= INVENTARIO ================= */
VIEWS.inventario=function(){ const v=S.config.venc; if(!UI.invTab||(!v&&UI.invTab==='lotes')) UI.invTab=v?'lotes':'mov';
  const t=tabs((v?[['lotes','Vencimientos']]:[]).concat([['mov','Movimientos'],['recuento','Recuento']]),UI.invTab,'tab-inv'); const f=UI.f.mov;
  return `${encab('Inventario','Lotes, movimientos de stock y recuentos',`<button class="btn pri" data-act="mov-nuevo">Registrar movimiento</button>`)}${t}
  ${UI.invTab==='mov'?`<div class="filters"><label class="field">Buscar<input data-bind="f.mov.q" value="${esc(f.q)}" placeholder="Producto o motivo"></label><label class="field">Tipo<select data-bind="f.mov.tipo">${opts([{v:'',t:'Todos'},'Entrada','Compra','Venta','Salida','Merma','Ajuste'],f.tipo)}</select></label><label class="field">Desde<input type="date" data-bind="f.mov.desde" value="${esc(f.desde)}"></label></div>`:''}<div id="res"></div>`; };
ACT['tab-inv']=el=>{ UI.invTab=el.dataset.t; render(); };
FILL.inventario=function(){ const r=$('#res'); if(!r) return;
  if(UI.invTab==='lotes'){ const l=S.lotes.filter(x=>x.cant>0&&x.vence&&prod(x.productoId)).sort((a,b)=>a.vence<b.vence?-1:1); const venc=l.filter(x=>difDias(x.vence,hoy())<0).length, porv=l.filter(x=>{const d=difDias(x.vence,hoy());return d>=0&&d<=S.config.diasVence;}).length;
    r.innerHTML=`<div class="kpis" style="margin-bottom:12px"><div class="kpi ${venc?'bad':''}"><div class="k">Lotes vencidos</div><div class="v">${venc}</div></div><div class="kpi ${porv?'warn':''}"><div class="k">Por vencer (${S.config.diasVence} días)</div><div class="v">${porv}</div></div><div class="kpi"><div class="k">Valor en riesgo</div><div class="v">${money(l.filter(x=>difDias(x.vence,hoy())<=S.config.diasVence).reduce((a,x)=>a+x.cant*(prod(x.productoId).costo),0))}</div><div class="d">a costo, vencido o por vencer</div></div></div>`+
      (l.length?`<div class="tw"><table><thead><tr><th>Producto</th><th>Lote</th><th>Vence</th><th>Estado</th><th class="n">Cantidad</th><th class="n">Valor a costo</th><th></th></tr></thead><tbody>${l.map(x=>{ const p=prod(x.productoId),e=estadoVence(x); return `<tr><td><b>${esc(p.nombre)}</b></td><td>${esc(x.lote)}</td><td>${fechaTxt(x.vence)}</td><td>${pill(e.k,e.t)}</td><td class="n">${qtyTxt(p,x.cant)}</td><td class="n">${money(x.cant*p.costo)}</td><td class="n">${e.d<=S.config.diasVence?`<button class="btn sm" data-act="lote-baja" data-id="${x.id}">${e.d<0?'Dar de baja':'Merma'}</button>`:''}</td></tr>`; }).join('')}</tbody></table></div>`:vacioHtml('No hay lotes con vencimiento cargado. Cargá la fecha de vencimiento al registrar una compra o una entrada.')); return; }
  if(UI.invTab==='recuento'){ const l=S.productos.filter(p=>p.activo).sort((a,b)=>(a.categoria||'').localeCompare(b.categoria||'')||a.nombre.localeCompare(b.nombre));
    r.innerHTML=`<p class="sm muted" style="margin-top:0">Contá lo que hay en el local y escribilo en «Contado». Solo se ajustan los que completes y que difieran del sistema. Para productos al peso usá kg.</p><div class="tw"><table><thead><tr><th>Producto</th><th class="n">En sistema</th><th class="n" style="width:140px">Contado</th><th class="n">Diferencia</th></tr></thead><tbody>${l.map(p=>`<tr><td>${esc(p.nombre)}<div class="sm muted">${esc(p.categoria||'')}</div></td><td class="n">${qtyTxt(p,stockDe(p.id))}</td><td class="n"><input id="rc_${p.id}" data-live="rc-dif" data-id="${p.id}" inputmode="decimal" style="text-align:right"></td><td class="n" id="rd_${p.id}"></td></tr>`).join('')}</tbody></table></div><div class="bar" style="margin-top:12px"><button class="btn pri" data-act="rc-aplicar">Aplicar ajustes</button></div>`; return; }
  const f=UI.f.mov,q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''); const l=S.movimientos.filter(m=>(!f.tipo||m.tipo===f.tipo)&&(!f.desde||m.fecha>=f.desde)&&(!q||((prod(m.productoId)||{}).nombre||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||(m.motivo||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))).sort((a,b)=>b.id-a.id).slice(0,300);
  const col={Entrada:'good',Compra:'good',Venta:'info',Salida:'warn',Merma:'bad',Ajuste:'mute'};
  r.innerHTML=l.length?`<div class="tw"><table><thead><tr><th>Fecha</th><th>Producto</th><th>Tipo</th><th class="n">Cantidad</th><th>Motivo</th></tr></thead><tbody>${l.map(m=>{ const p=prod(m.productoId); return `<tr><td>${fechaTxt(m.fecha)} ${m.hora||''}</td><td>${esc(p?p.nombre:'(borrado)')}</td><td>${pill(col[m.tipo]||'mute',m.tipo)}</td><td class="n b ${m.cant<0?'dn':'up'}">${m.cant>0?'+':''}${qtyTxt(p,m.cant)}</td><td>${esc(m.motivo)}</td></tr>`; }).join('')}</tbody></table></div>`:vacioHtml('No hay movimientos con esos filtros.'); };
AFTER.inventario=()=>FILL.inventario();
LIVE['rc-dif']=el=>{ const p=prod(+el.dataset.id); const v=num(el.value); const c=$('#rd_'+p.id); if(!c) return; if(v==null){ c.textContent=''; return; } const d=r3(v-stockDe(p.id)); c.innerHTML=Math.abs(d)<0.0001?'<span class="muted">Igual</span>':`<b class="${d<0?'dn':'up'}">${d>0?'+':''}${fmt(d,3).replace(/,?0+$/,'')}</b>`; };
ACT['rc-aplicar']=()=>{ let n=0; S.productos.forEach(p=>{ const el=$('#rc_'+p.id); if(!el||el.value.trim()==='') return; const v=num(el.value); if(v==null||v<0) return; if(moverStock(p.id,'Ajuste',v,'Recuento de inventario')) n++; }); indexar(); refrescar(); toast(n?n+' ajuste'+(n>1?'s':'')+' aplicado'+(n>1?'s':''):'No había diferencias para ajustar'); };
ACT['lote-baja']=el=>{ const l=S.lotes.find(x=>x.id===+el.dataset.id); const p=prod(l.productoId); confirmar('¿Dar de baja '+qtyTxt(p,l.cant)+' de «'+esc(p.nombre)+'» (lote '+esc(l.lote)+')? Se registra como merma valorizada a costo ('+money(l.cant*p.costo)+').',()=>{ bajaLote(l.id); indexar(); refrescar(); toast('Baja registrada'); },'Dar de baja'); };
ACT['mov-nuevo']=()=>moverForm(null);
function moverForm(p){ const campos=[{n:'pid',l:'Producto',t:'select',o:selProductos(!p),req:true,full:true},{n:'tipo',l:'Tipo de movimiento',t:'select',o:[{v:'Entrada',t:'Entrada (suma stock)'},{v:'Salida',t:'Salida (resta stock)'},{v:'Merma',t:'Merma o rotura (resta y se valoriza)'},{v:'Ajuste',t:'Ajuste (stock real contado)'}]},
  {n:'cant',l:'Cantidad (kg si se vende al peso)',t:'num',req:true,min:0},{n:'motivo',l:'Motivo',t:'text',list:['Reposición','Devolución','Rotura','Vencimiento','Uso interno','Recuento de inventario']},{n:'fecha',l:'Fecha',t:'date'}];
  if(S.config.venc) campos.push({n:'vence',l:'Vencimiento (solo entradas)',t:'date'},{n:'lote',l:'Lote (opcional)',t:'text'});
  formModal('Movimiento de stock',campos,{pid:p?p.id:'',fecha:hoy(),tipo:'Entrada'},d=>{ const pid=+d.pid; if(!pid) throw new Error('Elegí un producto.'); if(d.tipo!=='Ajuste'&&d.cant<=0) throw new Error('La cantidad tiene que ser mayor a 0.');
    if(d.tipo==='Entrada'&&S.config.venc&&d.vence) S.lotes.push({id:sig('L'),productoId:pid,lote:d.lote||'Manual',vence:d.vence,cant:d.cant,cantInicial:d.cant,compraId:0,fecha:d.fecha||hoy()});
    const ok=moverStock(pid,d.tipo,d.cant,d.motivo,d.fecha||hoy()); indexar(); cerrar(); refrescar(); toast(ok===false?'El stock ya coincidía, no hubo cambios':'Movimiento registrado'); }); }

/* ================= COMPRAS ================= */
VIEWS.compras=function(){ const t=tabs([['lista','Compras'],['pedido','Pedido sugerido']],UI.compTab,'tab-comp'); const f=UI.f.comp;
  return `${encab('Compras','Registro de compras, costo real y reposición',`<button class="btn pri" data-act="compra-nueva">Nueva compra</button>`)}${t}${UI.compTab==='lista'?`<div class="filters"><label class="field">Buscar<input data-bind="f.comp.q" value="${esc(f.q)}" placeholder="N° o proveedor"></label><label class="field">Desde<input type="date" data-bind="f.comp.desde" value="${esc(f.desde)}"></label></div>`:''}<div id="res"></div>`; };
ACT['tab-comp']=el=>{ UI.compTab=el.dataset.t; render(); };
FILL.compras=function(){ const r=$('#res'); if(!r) return;
  if(UI.compTab==='pedido'){ r.innerHTML=pedidoHtml(); return; }
  const f=UI.f.comp,q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''); const l=S.compras.filter(c=>(!f.desde||c.fecha>=f.desde)&&(!q||String(c.id)===q||provNom(c.proveedorId).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))).sort((a,b)=>b.id-a.id);
  const pend=S.compras.filter(c=>c.estado!=='Anulada'&&c.pago==='Pendiente').reduce((a,c)=>a+c.total,0);
  r.innerHTML=(pend>0?`<div class="banner warn" style="margin-bottom:10px"><span><b>${money(pend)}</b> en compras pendientes de pago a proveedores.</span></div>`:'')+(l.length?`<div class="tw"><table><thead><tr><th>N°</th><th>Fecha</th><th>Proveedor</th><th class="n">Ítems</th><th class="n">Total</th><th class="n">Costo real</th><th>Pago</th><th>Estado</th></tr></thead><tbody>${l.map(c=>`<tr class="click ${c.estado==='Anulada'?'off':''}" data-act="compra-ver" data-id="${c.id}"><td>#${c.id}</td><td>${fechaTxt(c.fecha)}</td><td>${dot((IDX.prov[c.proveedorId]||{}).color)}${esc(provNom(c.proveedorId))}</td><td class="n">${c.items.length}</td><td class="n b">${money(c.total)}</td><td class="n">${money(c.costoReal)}</td><td>${c.pago==='Pendiente'?pill('warn','Pendiente'):pill('mute',c.pago)}</td><td>${c.estado==='Anulada'?pill('bad','Anulada'):pill('good','Registrada')}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Todavía no registraste compras.')); };
AFTER.compras=()=>FILL.compras();
ACT['compra-ver']=el=>{ const c=S.compras.find(x=>x.id===+el.dataset.id);
  abrir('Compra #'+c.id+' · '+fechaTxt(c.fecha),`<p style="margin-top:0"><b>${esc(provNom(c.proveedorId))}</b> ${c.estado==='Anulada'?pill('bad','Anulada'):''} ${c.pago==='Pendiente'?pill('warn','Pendiente de pago'):'· pago: '+esc(c.pago)+(c.fechaPago?' el '+fechaTxt(c.fechaPago):'')}</p><div class="tw"><table><thead><tr><th>Producto</th><th class="n">Cantidad</th><th class="n">Precio</th><th class="n">Subtotal</th><th>Vence</th></tr></thead><tbody>${c.items.map(i=>{ const p=prod(i.productoId)||{nombre:'(borrado)'}; return `<tr><td>${esc(p.nombre)}</td><td class="n">${qtyTxt(p,i.cant)}</td><td class="n">${money2(i.costo)}</td><td class="n">${money2(i.cant*i.costo)}</td><td>${i.vence?fechaTxt(i.vence):'—'}</td></tr>`; }).join('')}</tbody></table></div>
  <div class="tw" style="margin-top:10px"><table><tbody><tr><td>Neto</td><td class="n">${money2(c.neto)}</td></tr><tr><td>IVA ${fmt(c.ivaPct,1)}% ${c.ivaRec?'(recuperable)':'(parte del costo)'}</td><td class="n">${money2(c.iva)}</td></tr><tr><td>Flete</td><td class="n">${money2(c.flete)}</td></tr><tr><td>Otros gastos</td><td class="n">${money2(c.otros)}</td></tr><tr class="tot"><td>Total pagado</td><td class="n">${money2(c.total)}</td></tr><tr class="tot"><td>Costo real</td><td class="n">${money2(c.costoReal)}</td></tr></tbody></table></div>${c.obs?`<p class="sm muted">Obs.: ${esc(c.obs)}</p>`:''}`,
  {wide:true,foot:`${c.estado!=='Anulada'?`<button class="btn bad" data-act="compra-anular" data-id="${c.id}">Anular compra</button>`:''}${c.estado!=='Anulada'&&c.pago==='Pendiente'?`<button class="btn" data-act="compra-pagar" data-id="${c.id}">Marcar como pagada</button>`:''}<button class="btn pri" data-act="cerrar">Cerrar</button>`}); };
ACT['compra-anular']=el=>{ const id=+el.dataset.id; confirmar('¿Anular la compra #'+id+'? Se descuenta del stock lo que había sumado y se dan de baja sus lotes. El historial de precios se conserva.',()=>{ anularCompra(id); indexar(); refrescar(); toast('Compra anulada'); },'Anular compra'); };
ACT['compra-pagar']=el=>{ const c=S.compras.find(x=>x.id===+el.dataset.id); formModal('Registrar pago de la compra #'+c.id,[{n:'medio',l:'Medio de pago',t:'select',o:['Efectivo','Transferencia']},{n:'fecha',l:'Fecha de pago',t:'date'}],{fecha:hoy()},d=>{ c.pago=d.medio; c.fechaPago=d.fecha||hoy(); guardar(); cerrar(); refrescar(); toast('Pago registrado'); }); };

/* nueva compra */
let CD=null;
function filaCompra(it,i){ return `<tr data-row="${i}"><td style="min-width:200px"><select data-live="cmp-row" data-i="${i}" data-k="pid" aria-label="Producto">${opts(selProductos(true),it.pid)}</select></td><td style="width:90px"><input data-live="cmp-row" data-i="${i}" data-k="cant" value="${esc(it.cant)}" inputmode="decimal" aria-label="Cantidad"></td><td style="width:110px"><input data-live="cmp-row" data-i="${i}" data-k="costo" value="${esc(it.costo)}" inputmode="decimal" aria-label="Costo unitario"></td>${S.config.venc?`<td style="width:140px"><input type="date" data-live="cmp-row" data-i="${i}" data-k="vence" value="${esc(it.vence)}" aria-label="Vencimiento"></td>`:''}<td class="n" id="cs_${i}" style="white-space:nowrap"></td><td><button class="btn sm ghost" data-act="cmp-del" data-i="${i}" aria-label="Quitar">✕</button></td></tr>`; }
function pintarFilasCompra(){ $('#cmprows').innerHTML=CD.items.map(filaCompra).join(''); totalCompra(); }
function leerItemsCompra(){ return CD.items.map(i=>({productoId:+i.pid||0,cant:num(i.cant)||0,costo:num(i.costo)||0,vence:i.vence||null,lote:''})); }
function totalCompra(){ const g=n=>{ const e=$('#cm_'+n); return e?e.value:''; };
  const items=leerItemsCompra(); const c=calcCompra({items,ivaPct:num(g('iva'))||0,ivaRec:$('#cm_ivarec').checked,flete:num(g('flete'))||0,otros:num(g('otros'))||0});
  items.forEach((it,i)=>{ const e=$('#cs_'+i); if(e) e.textContent=money2(it.cant*it.costo); });
  $('#ctot').innerHTML=`Neto <b>${money2(c.neto)}</b> &nbsp;·&nbsp; IVA <b>${money2(c.iva)}</b> &nbsp;·&nbsp; Total a pagar <b>${money2(c.total)}</b> &nbsp;·&nbsp; Costo real <b>${money2(c.costoReal)}</b>`; }
LIVE['cmp-row']=el=>{ const i=+el.dataset.i,k=el.dataset.k; CD.items[i][k]=el.value;
  if(k==='pid'){ const p=prod(+el.value); const vid=+$('#cm_prov').value; if(p){ const cat=S.catalogo.find(c=>c.productoId===p.id&&c.proveedorId===vid); CD.items[i].costo=fnum(cat?cat.precio:p.costo); } pintarFilasCompra(); } else totalCompra(); };
LIVE['cmp-top']=()=>totalCompra();
ACT['cmp-add']=()=>{ CD.items.push({pid:'',cant:'',costo:'',vence:''}); pintarFilasCompra(); };
ACT['cmp-del']=el=>{ CD.items.splice(+el.dataset.i,1); if(!CD.items.length) CD.items.push({pid:'',cant:'',costo:'',vence:''}); pintarFilasCompra(); };
ACT['compra-nueva']=()=>modalCompra(null);
function modalCompra(pre){
  if(!S.productos.length||!S.proveedores.length){ toast('Primero cargá al menos un proveedor y un producto.',true); return; }
  CD={items:(pre&&pre.items&&pre.items.length)?pre.items.map(i=>({pid:i.pid,cant:fnum(i.cant),costo:fnum(i.costo),vence:''})):[{pid:'',cant:'',costo:'',vence:''}]};
  const L=(n,l,inner)=>`<label class="field">${l}${inner}</label>`; const inp=(n,v,ph)=>`<input id="cm_${n}" data-live="cmp-top" value="${esc(v)}" inputmode="decimal" ${ph?`placeholder="${ph}"`:''}>`;
  abrir('Nueva compra',`<div class="frm" style="grid-template-columns:repeat(auto-fit,minmax(170px,1fr))">${L('fecha','Fecha',`<input type="date" id="cm_fecha" value="${hoy()}">`)}${L('prov','Proveedor',`<select id="cm_prov" data-live="cmp-top">${opts(selProveedores(),pre&&pre.proveedorId)}</select>`)}${L('pago','Pago',`<select id="cm_pago"><option>Efectivo</option><option>Transferencia</option><option>Pendiente</option></select>`)}${L('iva','IVA %',inp('iva',fnum(S.config.iva)))}${L('flete','Flete ($)',inp('flete','','0'))}${L('otros','Otros gastos ($)',inp('otros','','0'))}</div>
  <label class="field inline" style="margin:10px 0"><input type="checkbox" id="cm_ivarec" checked data-live="cmp-top"> El IVA es recuperable (crédito fiscal): no suma al costo real</label>
  <div class="tw"><table><thead><tr><th>Producto</th><th>Cantidad</th><th>Costo unit. sin IVA</th>${S.config.venc?'<th>Vence</th>':''}<th class="n">Subtotal</th><th></th></tr></thead><tbody id="cmprows"></tbody></table></div>
  <div class="bar" style="margin-top:8px"><button class="btn sm" data-act="cmp-add">+ Agregar producto</button></div><div id="ctot" style="margin-top:12px;font-size:15px"></div><label class="field" style="margin-top:10px">Observaciones<input id="cm_obs"></label><div id="err" class="sm dn" style="margin-top:8px" role="alert"></div>
  <p class="sm muted">Al guardar se suma el stock, se registran los precios del proveedor y el costo de cada producto se actualiza con el costo real (el flete y los otros gastos se reparten entre los productos).</p>`,
  {wide:true,noFocus:true,foot:`<button class="btn" data-act="cerrar">Cancelar</button><button class="btn pri" id="cmpok">Guardar compra</button>`});
  pintarFilasCompra(); $('#cmpok').onclick=guardarCompraForm; }
function guardarCompraForm(){ try{ const g=n=>$('#cm_'+n).value; const vid=+g('prov'); if(!vid) throw new Error('Elegí el proveedor.');
    const items=leerItemsCompra(); const vistos=new Set(); items.forEach((it,i)=>{ if(!it.productoId) throw new Error('Fila '+(i+1)+': elegí el producto.'); if(it.cant<=0) throw new Error('Fila '+(i+1)+': la cantidad tiene que ser mayor a 0.'); if(vistos.has(it.productoId)) throw new Error('Fila '+(i+1)+': el producto está repetido. Sumá las cantidades en una sola fila.'); vistos.add(it.productoId); });
    const id=crearCompra({fecha:g('fecha')||hoy(),proveedorId:vid,pago:g('pago'),ivaPct:num(g('iva'))||0,ivaRec:$('#cm_ivarec').checked,flete:num(g('flete'))||0,otros:num(g('otros'))||0,items,obs:g('obs')});
    cerrar(); indexar(); UI.compTab='lista'; if(UI.vista!=='compras') ir('compras'); else render(); toast('Compra #'+id+' registrada'); }catch(e){ $('#err').textContent=e.message; } }

/* pedido sugerido */
function gruposPedido(){ const g={}; S.productos.filter(p=>p.activo&&stockDe(p.id)<=p.minimo).forEach(p=>{ const q=sugerido(p); if(q<=0) return; const v=mejorProveedor(p.id)||0; (g[v]=g[v]||[]).push({p,q}); }); return g; }
function pedidoHtml(){ const g=gruposPedido(); const ks=Object.keys(g); if(!ks.length) return vacioHtml('No hay nada para reponer. Todos los productos están por encima del stock mínimo.');
  return `<p class="sm muted" style="margin-top:0">Productos en o bajo el mínimo, agrupados por el proveedor con el mejor precio. La cantidad sugerida cubre el doble del mínimo o unos 14 días de venta, lo que sea mayor. Podés editarla.</p>`+ks.map(k=>{ const v=IDX.prov[k];
    return `<div class="card" style="margin-bottom:12px" id="pg_${k}"><h2>${v?dot(v.color)+esc(v.nombre):'Sin proveedor asignado'} ${v&&v.telefono?`<span class="sm muted" style="font-weight:400">· ${esc(v.telefono)}</span>`:''}</h2><div class="tw"><table><thead><tr><th>Producto</th><th class="n">Stock</th><th class="n">Mínimo</th><th class="n" style="width:130px">Pedir</th><th class="n">Precio ref.</th></tr></thead><tbody>${g[k].map(({p,q})=>`<tr><td>${esc(p.nombre)}</td><td class="n ${stockDe(p.id)<=0?'dn b':''}">${qtyTxt(p,stockDe(p.id))}</td><td class="n">${qtyTxt(p,p.minimo)}</td><td class="n"><input data-live="ped" data-g="${k}" data-id="${p.id}" value="${fnum(q)}" inputmode="decimal" style="text-align:right;width:90px"></td><td class="n">${money2(precioReferencia(p.id)||p.costo)}${p.unidad==='kg'?'/kg':''}</td></tr>`).join('')}</tbody></table></div>
      <div class="bar" style="margin-top:10px"><button class="btn" data-act="ped-copiar" data-g="${k}">Copiar pedido</button>${v&&v.telefono?`<a class="btn" id="pw_${k}" target="_blank" rel="noopener" href="${wa(v.telefono,pedidoTxt(k))}">Enviar por WhatsApp</a>`:''}${v?`<button class="btn pri" data-act="ped-compra" data-g="${k}">Registrar compra</button>`:''}</div></div>`; }).join(''); }
function pedidoItems(k){ return [...document.querySelectorAll(`#pg_${k} input[data-live="ped"]`)].map(i=>({p:prod(+i.dataset.id),q:num(i.value)||0})).filter(x=>x.q>0); }
function pedidoTxt(k){ const v=IDX.prov[k]; const g=gruposPedido()[k]||[]; const its=document.querySelector('#pg_'+k)?pedidoItems(k):g.map(x=>({p:x.p,q:x.q}));
  return 'Hola'+(v&&v.contacto?' '+v.contacto:'')+', te paso el pedido de '+S.config.nombre+':\n'+its.map(x=>'• '+x.p.nombre+': '+(x.p.unidad==='kg'?fmt(x.q,2).replace(/,00$/,'')+' kg':fmt(x.q,0)+' u')).join('\n')+'\nGracias!'; }
LIVE.ped=el=>{ const k=el.dataset.g; const a=$('#pw_'+k); const v=IDX.prov[k]; if(a&&v) a.href=wa(v.telefono,pedidoTxt(k)); };
ACT['ped-copiar']=el=>copiar(pedidoTxt(el.dataset.g),'Pedido copiado');
ACT['ped-compra']=el=>{ const k=+el.dataset.g; modalCompra({proveedorId:k,items:pedidoItems(k).map(x=>({pid:x.p.id,cant:x.q,costo:(S.catalogo.find(c=>c.productoId===x.p.id&&c.proveedorId===k)||{precio:x.p.costo}).precio}))}); };

/* ================= PROVEEDORES ================= */
VIEWS.proveedores=function(){ const t=tabs([['prov','Proveedores'],['precios','Comparador de precios']],UI.provTab,'tab-prov'); const f=UI.f.pre;
  return `${encab('Proveedores','Contactos, catálogo de precios y deuda',`<button class="btn pri" data-act="prov-nuevo">Nuevo proveedor</button><button class="btn" data-act="precio-asignar">Asignar producto</button>`)}${t}${UI.provTab==='precios'?`<div class="filters"><label class="field">Buscar<input data-bind="f.pre.q" value="${esc(f.q)}" placeholder="Producto o proveedor"></label><label class="field">Ver<select data-bind="f.pre.ver">${opts([{v:'',t:'Todos los precios'},{v:'viejo',t:'Solo los desactualizados'},{v:'mejor',t:'Solo los mejores precios'}],f.ver)}</select></label></div>`:''}<div id="res"></div>`; };
ACT['tab-prov']=el=>{ UI.provTab=el.dataset.t; render(); };
FILL.proveedores=function(){ const r=$('#res'); if(!r) return;
  if(UI.provTab==='precios'){ const f=UI.f.pre,q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,''); const mejor={}; S.catalogo.forEach(c=>{ if(mejor[c.productoId]==null||c.precio<mejor[c.productoId]) mejor[c.productoId]=c.precio; });
    const l=S.catalogo.map(c=>({c,p:prod(c.productoId),d:difDias(hoy(),c.fecha),m:mejor[c.productoId]})).filter(x=>x.p&&(!q||x.p.nombre.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||provNom(x.c.proveedorId).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))&&(f.ver!=='viejo'||x.d>S.config.diasPrecio)&&(f.ver!=='mejor'||Math.abs(x.c.precio-x.m)<0.005)).sort((a,b)=>a.p.nombre.localeCompare(b.p.nombre));
    r.innerHTML=l.length?`<div class="tw"><table><thead><tr><th>Producto</th><th>Proveedor</th><th class="n">Precio</th><th>Actualizado</th><th>Comparación</th></tr></thead><tbody>${l.map(x=>`<tr class="click" data-act="precio-edit" data-id="${x.c.id}"><td><b>${esc(x.p.nombre)}</b></td><td>${dot((IDX.prov[x.c.proveedorId]||{}).color)}${esc(provNom(x.c.proveedorId))}</td><td class="n b">${money2(x.c.precio)}</td><td>${fechaTxt(x.c.fecha)} ${x.d>S.config.diasPrecio?pill('warn','hace '+x.d+' d'):''}</td><td>${Math.abs(x.c.precio-x.m)<0.005?pill('good','Mejor precio'):pill('mute','+'+fmt((x.c.precio-x.m)/x.m*100,1)+'% vs. el mejor')}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('No hay precios cargados todavía. Se cargan solos al registrar compras o con «Asignar producto».'); return; }
  const l=S.proveedores.slice().sort((a,b)=>a.nombre.localeCompare(b.nombre));
  r.innerHTML=l.length?`<div class="tw"><table><thead><tr><th>Proveedor</th><th>Contacto</th><th class="n">Productos</th><th class="n">Total comprado</th><th class="n">Pendiente de pago</th><th>Última compra</th></tr></thead><tbody>${l.map(v=>{ const cs=S.compras.filter(c=>c.proveedorId===v.id&&c.estado!=='Anulada'); const tot=cs.reduce((a,c)=>a+c.total,0), pend=cs.filter(c=>c.pago==='Pendiente').reduce((a,c)=>a+c.total,0); const uc=cs.map(c=>c.fecha).sort().pop();
    return `<tr class="click" data-act="prov-ver" data-id="${v.id}"><td>${dot(v.color)}<b>${esc(v.nombre)}</b></td><td>${esc(v.contacto||'')}<div class="sm muted">${esc(v.telefono||'')}</div></td><td class="n">${S.catalogo.filter(c=>c.proveedorId===v.id).length}</td><td class="n">${money(tot)}</td><td class="n ${pend>0?'dn b':''}">${money(pend)}</td><td>${fechaTxt(uc)}</td></tr>`; }).join('')}</tbody></table></div>`:vacioHtml('Todavía no cargaste proveedores.'); };
AFTER.proveedores=()=>FILL.proveedores();
const camposProv=[{n:'nombre',l:'Proveedor',t:'text',req:true,full:true},{n:'contacto',l:'Persona de contacto',t:'text'},{n:'telefono',l:'Teléfono / WhatsApp',t:'text',ph:'Con código de área'},{n:'email',l:'Email',t:'text'},{n:'direccion',l:'Dirección',t:'text'},{n:'color',l:'Color de sus productos',t:'color'},{n:'notas',l:'Notas',t:'area',full:true}];
ACT['prov-nuevo']=()=>provForm(null);
function provForm(v){ formModal(v?'Editar proveedor':'Nuevo proveedor',camposProv,v||{color:['#1d7a4e','#b4373d','#1f4fd8','#9a5a05','#7a3db5','#0f7c86'][S.proveedores.length%6]},d=>{
  if(S.proveedores.some(x=>x.nombre.toLowerCase()===d.nombre.toLowerCase()&&(!v||x.id!==v.id))) throw new Error('Ya existe un proveedor con ese nombre.');
  if(v) Object.assign(v,d); else S.proveedores.push(Object.assign({id:sig('V')},d)); indexar(); guardar(); cerrar(); refrescar(); toast('Proveedor guardado'); }); }
ACT['prov-ver']=el=>{ const v=IDX.prov[+el.dataset.id]; const cat=S.catalogo.filter(c=>c.proveedorId===v.id&&prod(c.productoId)); const mejor={}; S.catalogo.forEach(c=>{ if(mejor[c.productoId]==null||c.precio<mejor[c.productoId]) mejor[c.productoId]=c.precio; });
  const link=wa(v.telefono,'Hola '+(v.contacto||'')+'!');
  abrir(v.nombre,`<p style="margin-top:0">${esc(v.contacto||'')} ${v.telefono?'· '+esc(v.telefono):''} ${v.email?'· '+esc(v.email):''}<br><span class="muted">${esc(v.direccion||'')}</span></p>${v.notas?`<p class="sm muted">${esc(v.notas)}</p>`:''}
  <h2 style="font-size:20px">Catálogo de precios</h2>${cat.length?`<div class="tw"><table><thead><tr><th>Producto</th><th class="n">Precio</th><th>Actualizado</th><th>Comparación</th></tr></thead><tbody>${cat.map(c=>{ const p=prod(c.productoId); return `<tr class="click" data-act="precio-edit" data-id="${c.id}"><td>${esc(p.nombre)}</td><td class="n b">${money2(c.precio)}</td><td>${fechaTxt(c.fecha)}</td><td>${Math.abs(c.precio-mejor[c.productoId])<0.005?pill('good','Mejor precio'):pill('mute','+'+fmt((c.precio-mejor[c.productoId])/mejor[c.productoId]*100,1)+'%')}</td></tr>`; }).join('')}</tbody></table></div>`:vacioHtml('Todavía no tiene productos asignados.')}`,
  {wide:true,foot:`<button class="btn bad sm" data-act="prov-del" data-id="${v.id}">Eliminar</button><span style="flex:1"></span>${link?`<a class="btn" href="${link}" target="_blank" rel="noopener">WhatsApp</a>`:''}<button class="btn" data-act="prov-edit" data-id="${v.id}">Editar</button><button class="btn" data-act="precio-asignar" data-v="${v.id}">Asignar producto</button><button class="btn pri" data-act="cerrar">Cerrar</button>`}); };
ACT['prov-edit']=el=>provForm(IDX.prov[+el.dataset.id]);
ACT['prov-del']=el=>{ const v=IDX.prov[+el.dataset.id]; if(S.compras.some(c=>c.proveedorId===v.id)){ toast('«'+v.nombre+'» tiene compras registradas y no se puede borrar para no perder el historial.',true); return; }
  confirmar('¿Eliminar al proveedor «'+esc(v.nombre)+'» y sus precios?',()=>{ S.proveedores=S.proveedores.filter(x=>x.id!==v.id); S.catalogo=S.catalogo.filter(x=>x.proveedorId!==v.id); S.historial=S.historial.filter(x=>x.proveedorId!==v.id); indexar(); guardar(); refrescar(); toast('Proveedor eliminado'); },'Eliminar'); };
ACT['precio-asignar']=el=>{ if(!S.productos.length||!S.proveedores.length){ toast('Primero cargá al menos un producto y un proveedor.',true); return; }
  formModal('Asignar producto a un proveedor',[{n:'pid',l:'Producto',t:'select',o:selProductos(true),req:true,full:true},{n:'vid',l:'Proveedor',t:'select',o:selProveedores(),full:true},{n:'precio',l:'Precio de compra sin IVA ($)',t:'num',req:true,min:0},{n:'fecha',l:'Fecha del precio',t:'date'}],{vid:el.dataset.v||'',fecha:hoy()},d=>{
    if(!d.pid) throw new Error('Elegí el producto.'); registrarPrecio(+d.pid,+d.vid,d.precio,d.fecha||hoy(),'Manual'); guardar(); cerrar(); refrescar(); toast('Precio registrado'); }); };
ACT['precio-edit']=el=>{ const c=S.catalogo.find(x=>x.id===+el.dataset.id); const p=prod(c.productoId);
  formModal('Actualizar precio · '+p.nombre,[{n:'precio',l:'Precio de compra sin IVA ($) · '+provNom(c.proveedorId),t:'num',req:true,min:0,full:true},{n:'fecha',l:'Fecha del precio',t:'date'}],{precio:c.precio,fecha:hoy()},d=>{ registrarPrecio(c.productoId,c.proveedorId,d.precio,d.fecha||hoy(),'Manual'); guardar(); cerrar(); refrescar(); toast('Precio actualizado'); },{foot:`<button class="btn sm" type="button" data-act="prod-hist" data-id="${p.id}">Ver historial</button><span style="flex:1"></span>`}); };

/* ================= CLIENTES ================= */
VIEWS.clientes=function(){ const f=UI.f.cli;
  return `${encab('Clientes','Fichas, cuenta corriente y cobros',`<button class="btn pri" data-act="cli-nuevo">Nuevo cliente</button>`)}<div class="filters"><label class="field">Buscar<input data-bind="f.cli.q" value="${esc(f.q)}" placeholder="Nombre o teléfono"></label></div><div id="res"></div>`; };
FILL.clientes=function(){ const r=$('#res'); if(!r) return; const q=UI.f.cli.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  const l=S.clientes.filter(c=>!q||c.nombre.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||(c.telefono||'').includes(q)).sort((a,b)=>saldoCliente(b.id)-saldoCliente(a.id)||a.nombre.localeCompare(b.nombre));
  r.innerHTML=l.length?`<div class="tw"><table><thead><tr><th>Cliente</th><th>Teléfono</th><th class="n">Saldo a cobrar</th><th class="n">Compras</th><th class="n">Total comprado</th><th>Última compra</th></tr></thead><tbody>${l.map(c=>{ const vs=S.ventas.filter(v=>v.clienteId===c.id&&v.estado!=='Anulada'); const s=saldoCliente(c.id);
    return `<tr class="click" data-act="cli-ver" data-id="${c.id}"><td><b>${esc(c.nombre)}</b></td><td>${esc(c.telefono||'')}</td><td class="n b ${s>0?'dn':''}">${money(s)}</td><td class="n">${vs.length}</td><td class="n">${money(vs.reduce((a,v)=>a+v.total,0))}</td><td>${fechaTxt(vs.map(v=>v.fecha).sort().pop())}</td></tr>`; }).join('')}</tbody></table></div>`:vacioHtml('Todavía no cargaste clientes. Los clientes sirven para vender en cuenta corriente y ver quién compra más.'); };
AFTER.clientes=()=>FILL.clientes();
const camposCli=[{n:'nombre',l:'Nombre',t:'text',req:true,full:true},{n:'telefono',l:'Teléfono / WhatsApp',t:'text',ph:'Con código de área'},{n:'direccion',l:'Dirección',t:'text'},{n:'notas',l:'Notas',t:'area',full:true}];
ACT['cli-nuevo']=()=>cliForm(null);
function cliForm(c){ formModal(c?'Editar cliente':'Nuevo cliente',camposCli,c||{},d=>{ if(c) Object.assign(c,d); else S.clientes.push(Object.assign({id:sig('Q'),creado:hoy()},d)); indexar(); guardar(); cerrar(); refrescar(); toast('Cliente guardado'); }); }
ACT['cli-edit']=el=>cliForm(IDX.cli[+el.dataset.id]);
ACT['cli-ver']=el=>{ const c=IDX.cli[+el.dataset.id]; const s=saldoCliente(c.id); const vs=S.ventas.filter(v=>v.clienteId===c.id).sort((a,b)=>b.id-a.id).slice(0,12); const cb=S.cobros.filter(x=>x.clienteId===c.id).sort((a,b)=>b.id-a.id).slice(0,8);
  const link=s>0?wa(c.telefono,'Hola '+c.nombre+', te escribimos de '+S.config.nombre+'. Tu saldo pendiente es de '+money(s)+'. ¡Gracias!'):'';
  abrir(c.nombre,`<div class="kpis" style="margin-bottom:12px"><div class="kpi ${s>0?'bad':'good'}"><div class="k">Saldo a cobrar</div><div class="v">${money(s)}</div></div><div class="kpi"><div class="k">Contacto</div><div class="v" style="font-size:16px">${esc(c.telefono||'—')}</div><div class="d">${esc(c.direccion||'')}</div></div></div>
  <div class="grid g2"><div><h2 style="font-size:20px">Últimas compras</h2>${vs.length?`<div class="tw"><table><tbody>${vs.map(v=>`<tr class="${v.estado==='Anulada'?'off':''}"><td>${fechaCorta(v.fecha)}</td><td>#${v.id}</td><td>${esc(v.medio)}</td><td class="n">${money(v.total)}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Sin compras.')}</div>
  <div><h2 style="font-size:20px">Cobros registrados</h2>${cb.length?`<div class="tw"><table><tbody>${cb.map(x=>`<tr><td>${fechaCorta(x.fecha)}</td><td>${esc(x.medio)}</td><td class="n up b">${money(x.monto)}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Sin cobros.')}</div></div>`,
  {wide:true,foot:`${link?`<a class="btn" href="${link}" target="_blank" rel="noopener">Recordar saldo por WhatsApp</a>`:''}<button class="btn" data-act="cli-edit" data-id="${c.id}">Editar</button>${s>0?`<button class="btn pri" data-act="cli-cobro" data-id="${c.id}">Registrar cobro</button>`:''}<button class="btn" data-act="cerrar">Cerrar</button>`}); };
ACT['cli-cobro']=el=>{ const c=IDX.cli[+el.dataset.id]; const s=saldoCliente(c.id);
  formModal('Registrar cobro · '+c.nombre,[{n:'monto',l:'Monto cobrado ($)',t:'num',req:true,min:0.01},{n:'medio',l:'Medio',t:'select',o:MEDIOS.filter(m=>m!=='Cuenta corriente')},{n:'fecha',l:'Fecha',t:'date'},{n:'nota',l:'Nota',t:'text'}],{monto:s,fecha:hoy()},d=>{ if(d.monto>s+0.005) throw new Error('El cobro supera el saldo ('+money2(s)+').'); S.cobros.push({id:sig('Z'),fecha:d.fecha||hoy(),clienteId:c.id,monto:d.monto,medio:d.medio,nota:d.nota}); guardar(); cerrar(); refrescar(); toast('Cobro registrado'); }); };

/* ================= GASTOS ================= */
VIEWS.gastos=function(){ const f=UI.f.gas;
  return `${encab('Gastos','Alquiler, servicios, sueldos y otros costos del negocio',`<button class="btn pri" data-act="gasto-nuevo">Nuevo gasto</button>`)}<div class="filters"><label class="field">Buscar<input data-bind="f.gas.q" value="${esc(f.q)}" placeholder="Concepto o categoría"></label><label class="field">Desde<input type="date" data-bind="f.gas.desde" value="${esc(f.desde)}"></label></div><div id="res"></div>`; };
FILL.gastos=function(){ const r=$('#res'); if(!r) return; const f=UI.f.gas,q=f.q.trim().toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'');
  const l=S.gastos.filter(g=>(!f.desde||g.fecha>=f.desde)&&(!q||g.concepto.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q)||(g.categoria||'').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g,'').includes(q))).sort((a,b)=>a.fecha<b.fecha?1:-1);
  const tot=l.reduce((a,g)=>a+g.monto+g.iva,0);
  r.innerHTML=l.length?`<div class="sm muted" style="margin-bottom:6px">${l.length} gasto${l.length>1?'s':''} · total ${money(tot)}</div><div class="tw"><table><thead><tr><th>Fecha</th><th>Concepto</th><th>Categoría</th><th class="n">Monto</th><th class="n">IVA</th><th class="n">Total</th><th>Pago</th></tr></thead><tbody>${l.map(g=>`<tr class="click" data-act="gasto-edit" data-id="${g.id}"><td>${fechaTxt(g.fecha)}</td><td>${esc(g.concepto)}</td><td>${g.categoria?pill('mute',g.categoria):''}</td><td class="n">${money(g.monto)}</td><td class="n">${money(g.iva)}${g.ivaRec&&g.iva?' <span class="sm muted">rec.</span>':''}</td><td class="n b">${money(g.monto+g.iva)}</td><td>${esc(g.medio||'')}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('No hay gastos con esos filtros.'); };
AFTER.gastos=()=>FILL.gastos();
ACT['gasto-nuevo']=()=>gastoForm(null); ACT['gasto-edit']=el=>gastoForm(S.gastos.find(g=>g.id===+el.dataset.id));
function gastoForm(g){ const cs=[...new Set(S.gastos.map(x=>x.categoria).filter(Boolean).concat(['Alquiler','Servicios','Sueldos','Impuestos','Insumos','Mantenimiento','Varios']))];
  formModal(g?'Editar gasto':'Nuevo gasto',[{n:'fecha',l:'Fecha',t:'date'},{n:'concepto',l:'Concepto',t:'text',req:true},{n:'categoria',l:'Categoría',t:'text',list:cs},{n:'medio',l:'Se pagó con',t:'select',o:['Efectivo','Transferencia','Débito','Crédito','Otro']},{n:'monto',l:'Monto sin IVA ($)',t:'num',req:true,min:0},{n:'iva',l:'IVA ($)',t:'num',min:0},{n:'ivaRec',l:'El IVA es recuperable (crédito fiscal)',t:'check',full:true}],g||{fecha:hoy(),medio:'Efectivo'},d=>{
    if(g) Object.assign(g,d); else S.gastos.push(Object.assign({id:sig('G')},d)); guardar(); cerrar(); refrescar(); toast('Gasto guardado'); },{foot:g?`<button class="btn bad sm" type="button" data-act="gasto-del" data-id="${g.id}">Eliminar</button><span style="flex:1"></span>`:''}); }
ACT['gasto-del']=el=>confirmar('¿Eliminar este gasto?',()=>{ S.gastos=S.gastos.filter(g=>g.id!==+el.dataset.id); guardar(); refrescar(); toast('Gasto eliminado'); },'Eliminar');

/* ================= REPORTES ================= */
function periodo(){ const h=hoy(),R=UI.rep; const d=new Date(); const ini=ymd(new Date(d.getFullYear(),d.getMonth(),1)); const iniP=ymd(new Date(d.getFullYear(),d.getMonth()-1,1)); const finP=ymd(new Date(d.getFullYear(),d.getMonth(),0));
  return {hoy:[h,h],'7d':[addDias(h,-6),h],mes:[ini,h],ant:[iniP,finP],'30d':[addDias(h,-29),h],custom:[R.desde||h,R.hasta||h]}[R.per]; }
VIEWS.reportes=function(){ const R=UI.rep;
  return `${encab('Reportes','Rentabilidad, rotación y capital inmovilizado',`<button class="btn" data-act="rep-csv">Exportar ventas (CSV)</button>`)}<div class="filters"><label class="field">Período<select data-bind="rep.per">${opts([{v:'hoy',t:'Hoy'},{v:'7d',t:'Últimos 7 días'},{v:'mes',t:'Este mes'},{v:'ant',t:'Mes anterior'},{v:'30d',t:'Últimos 30 días'},{v:'custom',t:'Personalizado'}],R.per)}</select></label>
  ${R.per==='custom'?`<label class="field">Desde<input type="date" data-bind="rep.desde" value="${esc(R.desde)}"></label><label class="field">Hasta<input type="date" data-bind="rep.hasta" value="${esc(R.hasta)}"></label>`:''}</div><div id="res"></div>`; };
FILL.reportes=function(){ const r=$('#res'); if(!r) return; const [d,h]=periodo(); const R=reporte(d,h);
  const ctrl=document.querySelector('.filters'); if(ctrl&&((UI.rep.per==='custom')!==!!ctrl.querySelector('[data-bind="rep.desde"]'))){ render(); return; }
  const pr=R.prods.map(p=>({...p,gan:p.ing-p.cst})).sort((a,b)=>b.gan-a.gan); const mx=Math.max(1,...pr.map(p=>p.gan));
  const desde30=addDias(hoy(),-30); const vend=new Set(); S.ventas.forEach(v=>{ if(v.estado!=='Anulada'&&v.fecha>=desde30) v.items.forEach(i=>vend.add(i.productoId)); });
  const parado=S.productos.filter(p=>p.activo&&stockDe(p.id)>0&&!vend.has(p.id)); const valorParado=parado.reduce((a,p)=>a+stockDe(p.id)*p.costo,0);
  r.innerHTML=`<div class="sm muted" style="margin-bottom:8px">Del ${fechaTxt(d)} al ${fechaTxt(h)} · ${R.vs.length} ventas</div>
  <div class="kpis"><div class="kpi"><div class="k">Ventas</div><div class="v">${money(R.ingresos)}</div></div><div class="kpi"><div class="k">Costo de la mercadería vendida</div><div class="v">${money(R.costo)}</div></div><div class="kpi good"><div class="k">Margen bruto</div><div class="v">${money(R.bruto)}</div><div class="d">${R.ingresos>0?fmt(R.bruto/R.ingresos*100,1)+'% de las ventas':''}</div></div>
   <div class="kpi"><div class="k">Gastos</div><div class="v">${money(R.gastos)}</div></div><div class="kpi ${R.mermas>0?'warn':''}"><div class="k">Mermas</div><div class="v">${money(R.mermas)}</div><div class="d">valorizadas a costo</div></div><div class="kpi ${R.neto>=0?'good':'bad'}"><div class="k">Resultado</div><div class="v">${money(R.neto)}</div><div class="d">margen bruto − gastos − mermas</div></div></div>
  <div class="grid g2"><div class="card"><h2>Productos que más ganancia dejan</h2>${pr.length?`<div class="tw"><table><thead><tr><th>Producto</th><th class="n">Vendido</th><th class="n">Ventas</th><th class="n">Ganancia</th><th class="n">Margen</th></tr></thead><tbody>${pr.slice(0,12).map(p=>`<tr><td>${esc(p.nombre)}</td><td class="n">${p.unidad==='kg'?fmt(p.cant,2)+' kg':fmt(p.cant,0)}</td><td class="n">${money(p.ing)}</td><td class="n b">${money(p.gan)}</td><td class="n">${p.ing>0?fmt(p.gan/p.ing*100,0)+'%':'—'}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Sin ventas en el período.')}</div>
  <div class="card"><h2>Por categoría</h2>${Object.keys(R.cats).length?Object.entries(R.cats).sort((a,b)=>b[1].ing-a[1].ing).map(([k,v])=>`<div class="hb"><span>${esc(k)}</span><div class="tr"><div class="fl" style="width:${v.ing/Math.max(1,R.ingresos)*100}%"></div></div><b>${money(v.ing)}</b></div>`).join(''):vacioHtml('Sin datos.')}
   <h2 style="margin-top:16px">Medios de pago</h2>${Object.keys(R.medios).length?Object.entries(R.medios).sort((a,b)=>b[1]-a[1]).map(([k,v])=>`<div class="hb"><span>${esc(k)}</span><div class="tr"><div class="fl" style="width:${v/Math.max(1,R.ingresos)*100}%"></div></div><b>${money(v)}</b></div>`).join(''):vacioHtml('Sin datos.')}</div></div>
  <div class="card"><h2>Stock sin movimiento en 30 días</h2><p class="sm muted" style="margin-top:0">Plata inmovilizada en productos que no se vendieron en el último mes: <b>${money(valorParado)}</b>. Pensá en promociones o en no volver a comprarlos.</p>${parado.length?`<div class="tw"><table><thead><tr><th>Producto</th><th class="n">Stock</th><th class="n">Valor a costo</th></tr></thead><tbody>${parado.sort((a,b)=>stockDe(b.id)*b.costo-stockDe(a.id)*a.costo).slice(0,10).map(p=>`<tr><td>${esc(p.nombre)}</td><td class="n">${qtyTxt(p,stockDe(p.id))}</td><td class="n">${money(stockDe(p.id)*p.costo)}</td></tr>`).join('')}</tbody></table></div>`:vacioHtml('Todo lo que tenés en stock se vendió en el último mes.')}</div>`; };
AFTER.reportes=()=>FILL.reportes();
ACT['rep-csv']=()=>{ const [d,h]=periodo(); const rows=[]; ventasValidas(d,h).forEach(v=>v.items.forEach(i=>rows.push([v.id,v.fecha,v.hora||'',cliNom(v.clienteId),v.medio,i.nombre,String(i.cant).replace('.',','),String(i.precio).replace('.',','),String(i.costo).replace('.',','),String(r2(i.cant*i.precio)).replace('.',',')])));
  if(!rows.length){ toast('No hay ventas en el período.',true); return; } descargar('ventas_'+d+'_a_'+h+'.csv',aCSV(['venta','fecha','hora','cliente','medio de pago','producto','cantidad','precio','costo','subtotal'],rows)); };

/* ================= AJUSTES ================= */
VIEWS.ajustes=function(){ const c=S.config; const ur=c.ultimoRespaldo;
  return `${encab('Ajustes','Tu negocio, respaldo y migración de datos')}
  ${S._guardadoOk===false?'<div class="banner warn"><span><b>Este navegador no está guardando los datos.</b> Hacé un respaldo ahora y revisá que el navegador permita almacenamiento local.</span></div>':''}
  <div class="card"><h2>Negocio</h2><form id="cfg" class="frm" autocomplete="off"><label class="field">Nombre<input name="nombre" value="${esc(c.nombre)}"></label><label class="field">Subtítulo<input name="sub" value="${esc(c.sub||'')}"></label>
   <label class="field">Rubro (ajusta módulos)<select name="rubro" data-chg="rubro">${opts(Object.keys(RUBROS),c.rubro)}</select></label><label class="field">Moneda<input name="moneda" value="${esc(c.moneda)}"></label>
   <label class="field inline"><input type="checkbox" name="venc" ${c.venc?'checked':''}> Controlar vencimientos y lotes</label><label class="field inline"><input type="checkbox" name="peso" ${c.peso?'checked':''}> Vendo productos al peso (kg)</label>
   <label class="field">IVA habitual en compras (%)<input name="iva" value="${fnum(c.iva)}" inputmode="decimal"></label><label class="field">Avisar vencimientos con (días)<input name="diasVence" value="${c.diasVence}" inputmode="numeric"></label><label class="field">Precio desactualizado después de (días)<input name="diasPrecio" value="${c.diasPrecio}" inputmode="numeric"></label>
   <label class="field">Logo de tu negocio (opcional)<input type="file" id="logof" accept="image/*"></label></form><div class="bar" style="margin-top:12px"><button class="btn pri" data-act="cfg-guardar">Guardar ajustes</button><button class="btn" data-act="logo-reset">Quitar logo</button></div></div>
  <div class="grid g2"><div class="card"><h2>Respaldo</h2><p class="sm muted" style="margin-top:0">Tus datos se guardan en este navegador. Si borrás los datos del navegador o cambiás de computadora se pierden, por eso hay que respaldarlos seguido. ${ur?'Último respaldo: <b>'+fechaTxt(ur)+'</b>.':'<b>Todavía no hiciste ninguno.</b>'}</p>
   <div class="bar"><button class="btn pri" data-act="resp-exp">Descargar respaldo</button><label class="btn">Restaurar respaldo<input type="file" id="respf" accept=".json" hidden></label></div></div>
   <div class="card"><h2>Pasar los datos del programa anterior</h2><p class="sm muted" style="margin-top:0">Elegí el archivo <b>gestion.json</b> de la carpeta «Datos» del programa de escritorio. Se importan productos, proveedores, precios, compras, gastos y movimientos de stock. <b>Reemplaza los datos actuales.</b></p>
   <label class="btn">Elegir gestion.json<input type="file" id="gestf" accept=".json" hidden></label><div id="gestr" class="sm" style="margin-top:8px"></div></div></div>
  <div class="card"><h2>Datos</h2><div class="bar"><button class="btn" data-act="demo-cargar">Cargar datos de ejemplo</button><button class="btn bad" data-act="vaciar">Empezar con datos vacíos</button></div><p class="sm muted">${S.config.demo?'Ahora estás viendo datos de ejemplo. Cuando quieras empezar en serio, usá «Empezar con datos vacíos» o importá tu gestion.json.':''}</p></div>`; };
CHG.rubro=el=>{ aplicarRubro(el.value); const f=$('#cfg'); f.elements.venc.checked=S.config.venc; f.elements.peso.checked=S.config.peso; };
ACT['cfg-guardar']=()=>{ const f=$('#cfg').elements; const c=S.config; const iva=num(f.iva.value),dv=num(f.diasVence.value),dp=num(f.diasPrecio.value);
  if(iva==null||dv==null||dp==null||!f.nombre.value.trim()){ toast('Revisá el nombre y los números.',true); return; }
  Object.assign(c,{nombre:f.nombre.value.trim(),sub:f.sub.value.trim(),rubro:f.rubro.value,moneda:f.moneda.value.trim()||'$',venc:f.venc.checked,peso:f.peso.checked,iva,diasVence:Math.round(dv),diasPrecio:Math.round(dp)}); guardar(); pintarMarco(); render(); toast('Ajustes guardados'); };
ACT['logo-reset']=()=>{ S.config.logo=''; guardar(); pintarMarco(); toast('Logo quitado'); };
ACT['resp-exp']=()=>{ const t=exportarJSON(); descargar('respaldo_'+S.config.nombre.toLowerCase().replace(/[^a-z0-9]+/g,'_')+'_'+hoy()+'.json',t); setTimeout(()=>{ if(UI.vista==='ajustes') render(); },300); };
ACT['demo-cargar']=()=>confirmar('Se reemplazan los datos actuales por los de ejemplo. ¿Seguir?',()=>{ cargarDemo(); pintarMarco(); render(); toast('Datos de ejemplo cargados'); },'Cargar ejemplo',false);
ACT.vaciar=()=>confirmar('Se borran <b>todos</b> los productos, ventas, compras y clientes. Esto no se puede deshacer. Si no hiciste un respaldo, hacelo antes.',()=>{ const c=S.config; S=vacio(); S.config=Object.assign(S.config,c,{demo:false}); indexar(); guardar(); pintarMarco(); ir('panel'); render(); toast('Listo, empezás de cero'); },'Borrar todo');
document.addEventListener('change',e=>{ const el=e.target;
  if(el.id==='respf'&&el.files[0]){ const rd=new FileReader(); rd.onload=()=>confirmar('Se reemplazan los datos actuales por los del respaldo. ¿Seguir?',()=>{ try{ importarJSON(String(rd.result)); pintarMarco(); render(); toast('Respaldo restaurado'); }catch(err){ toast(err.message,true); } },'Restaurar',false); rd.readAsText(el.files[0]); el.value=''; }
  if(el.id==='gestf'&&el.files[0]){ const rd=new FileReader(); rd.onload=()=>{ let o; try{ o=JSON.parse(String(rd.result).replace(/^﻿/,'')); }catch(err){ $('#gestr').innerHTML='<span class="dn">El archivo no es un JSON válido.</span>'; return; }
      if(!o||(!o.Productos&&!o.Proveedores)){ $('#gestr').innerHTML='<span class="dn">No parece un gestion.json del programa anterior.</span>'; return; }
      confirmar('Se reemplazan los datos actuales por los del programa anterior ('+(o.Productos||[]).length+' productos). ¿Seguir?',()=>{ try{ const r=importarGestion(o); pintarMarco(); ir('productos'); abrir('Importación lista','<p style="margin-top:0">Se importaron <b>'+r.productos+' productos</b>, '+r.proveedores+' proveedores, '+r.compras+' compras y '+r.movimientos+' movimientos de stock.</p><p class="muted">El programa anterior no distinguía unidades: todos los productos quedaron «por unidad». Los que vendés al peso pasalos a kg con el botón <b>Unidad por categoría</b> o desde la ficha de cada uno.</p>',{foot:'<button class="btn pri" data-act="cerrar">Entendido</button>'}); }catch(err){ toast('No se pudo importar: '+err.message,true); } },'Importar',false); }; rd.readAsText(el.files[0]); el.value=''; }
  if(el.id==='logof'&&el.files[0]){ const rd=new FileReader(); rd.onload=()=>{ const im=new Image(); im.onload=()=>{ const s=192,cv=document.createElement('canvas'); cv.width=cv.height=s; const x=cv.getContext('2d'); const m=Math.min(im.width,im.height); x.drawImage(im,(im.width-m)/2,(im.height-m)/2,m,m,0,0,s,s); S.config.logo=cv.toDataURL('image/png'); guardar(); pintarMarco(); toast('Logo actualizado'); }; im.onerror=()=>toast('No pude leer esa imagen.',true); im.src=String(rd.result); }; rd.readAsDataURL(el.files[0]); el.value=''; } });

/* ================= ARRANQUE ================= */
window.addEventListener('hashchange',()=>{ const v=location.hash.slice(1); if(VIEWS[v]){ UI.vista=v; render(); } });
(function arrancar(){
  S=cargar(); if(S){ S=Object.assign(vacio(),S); S.config=Object.assign(vacio().config,S.config); if(S.config.logo==='logo.png') S.config.logo=''; indexar(); } else cargarDemo();
  const v=location.hash.slice(1); if(VIEWS[v]) UI.vista=v;
  pintarMarco(); render(); })();
